#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

typedef struct TreeNode {
    int val;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

static void skip_ws(const char* s, size_t* p) {
    while (s[*p] && isspace((unsigned char)s[*p])) (*p)++;
}

static TreeNode* new_node(int v) {
    TreeNode* n = (TreeNode*)malloc(sizeof(TreeNode));
    n->val = v; n->left = NULL; n->right = NULL;
    return n;
}

static int parse_nullable(const char* s, size_t* p, int* is_null) {
    skip_ws(s, p);
    if (strncmp(s + *p, "null", 4) == 0) {
        *p += 4; *is_null = 1; return 0;
    }
    *is_null = 0;
    char* end;
    long v = strtol(s + *p, &end, 10);
    if (end == s + *p) exit(1);
    *p = (size_t)(end - s);
    return (int)v;
}

static TreeNode* parse_tree(const char* s, size_t* p) {
    skip_ws(s, p);
    if (s[*p] != '[') exit(1);
    (*p)++;
    skip_ws(s, p);
    if (s[*p] == ']') { (*p)++; return NULL; }

    int cap = 16, n = 0;
    TreeNode** nodes = (TreeNode**)malloc((size_t)cap * sizeof(TreeNode*));
    while (1) {
        int is_null;
        int value = parse_nullable(s, p, &is_null);
        if (n == cap) {
            cap *= 2;
            nodes = (TreeNode**)realloc(nodes, (size_t)cap * sizeof(TreeNode*));
        }
        nodes[n++] = is_null ? NULL : new_node(value);
        skip_ws(s, p);
        if (s[*p] == ',') { (*p)++; continue; }
        if (s[*p] == ']') { (*p)++; break; }
        exit(1);
    }

    if (n == 0 || nodes[0] == NULL) {
        free(nodes);
        return NULL;
    }

    int qcap = n, head = 0, tail = 0;
    TreeNode** q = (TreeNode**)malloc((size_t)qcap * sizeof(TreeNode*));
    q[tail++] = nodes[0];
    int i = 1;
    while (head < tail && i < n) {
        TreeNode* cur = q[head++];
        if (i < n && nodes[i] != NULL) { cur->left = nodes[i]; q[tail++] = nodes[i]; }
        i++;
        if (i < n && nodes[i] != NULL) { cur->right = nodes[i]; q[tail++] = nodes[i]; }
        i++;
    }
    TreeNode* root = nodes[0];
    free(q); free(nodes);
    return root;
}

static bool hasPathSum(TreeNode* root, int targetSum) {
    if (!root) return false;
    int cap = 16, top = 0;
    TreeNode** ns = (TreeNode**)malloc((size_t)cap * sizeof(TreeNode*));
    int* sums = (int*)malloc((size_t)cap * sizeof(int));
    ns[top] = root; sums[top] = root->val; top++;
    while (top > 0) {
        --top;
        TreeNode* node = ns[top];
        int sum = sums[top];
        if (!node->left && !node->right) {
            if (sum == targetSum) { free(ns); free(sums); return true; }
            continue;
        }
        if (node->right) {
            if (top == cap) { cap *= 2; ns = (TreeNode**)realloc(ns, (size_t)cap * sizeof(TreeNode*)); sums = (int*)realloc(sums, (size_t)cap * sizeof(int)); }
            ns[top] = node->right; sums[top] = sum + node->right->val; top++;
        }
        if (node->left) {
            if (top == cap) { cap *= 2; ns = (TreeNode**)realloc(ns, (size_t)cap * sizeof(TreeNode*)); sums = (int*)realloc(sums, (size_t)cap * sizeof(int)); }
            ns[top] = node->left; sums[top] = sum + node->left->val; top++;
        }
    }
    free(ns); free(sums);
    return false;
}

