static vector<optional<int>> parseTreeArray(const string& s, size_t& p) {
    skipws(s, p);
    if (p >= s.size() || s[p] != '[') throw runtime_error("invalid tree array");
    ++p;
    vector<optional<int>> vals;
    skipws(s, p);
    if (p < s.size() && s[p] == ']') { ++p; return vals; }
    while (true) {
        skipws(s, p);
        if (s.compare(p, 4, "null") == 0) { vals.push_back(nullopt); p += 4; }
        else {
            size_t st = p;
            if (p < s.size() && (s[p] == '-' || s[p] == '+')) ++p;
            while (p < s.size() && isdigit(static_cast<unsigned char>(s[p]))) ++p;
            if (st == p) throw runtime_error("invalid integer");
            vals.push_back(stoi(s.substr(st, p - st)));
        }
        skipws(s, p);
        if (p < s.size() && s[p] == ',') { ++p; continue; }
        if (p < s.size() && s[p] == ']') { ++p; break; }
        throw runtime_error("invalid tree serialization");
    }
    return vals;
}

static TreeNode* buildTree(const vector<optional<int>>& vals) {
    if (vals.empty() || !vals[0].has_value()) return nullptr;
    vector<TreeNode*> nodes(vals.size(), nullptr);
    for (size_t i = 0; i < vals.size(); ++i) if (vals[i].has_value()) nodes[i] = new TreeNode(*vals[i]);
    queue<TreeNode*> q;
    q.push(nodes[0]);
    size_t i = 1;
    while (!q.empty() && i < nodes.size()) {
        TreeNode* node = q.front(); q.pop();
        if (i < nodes.size() && nodes[i]) { node->left = nodes[i]; q.push(nodes[i]); }
        ++i;
        if (i < nodes.size() && nodes[i]) { node->right = nodes[i]; q.push(nodes[i]); }
        ++i;
    }
    return nodes[0];
}

static bool hasPathSum(TreeNode* root, int targetSum) {
    if (!root) return false;
    vector<pair<TreeNode*, int>> st{{root, root->val}};
    while (!st.empty()) {
        auto [node, sum] = st.back();
        st.pop_back();
        if (!node->left && !node->right) {
            if (sum == targetSum) return true;
            continue;
        }
        if (node->right) st.push_back({node->right, sum + node->right->val});
        if (node->left) st.push_back({node->left, sum + node->left->val});
    }
    return false;
}

